--
-- Name: active_route_summaries; Type: VIEW; Schema: transport; Owner: -
--

CREATE VIEW transport.active_route_summaries AS
 WITH route_totals AS (
         SELECT r.service_no,
            r.direction,
            min(r.stop_sequence) FILTER (WHERE st.is_active) AS first_sequence,
            max(r.stop_sequence) FILTER (WHERE st.is_active) AS last_sequence,
            count(*) FILTER (WHERE st.is_active) AS observed_stop_count,
            (bool_and(st.is_active) AND (min(r.stop_sequence) = 1) AND (count(*) = max(r.stop_sequence))) AS sequence_gap_free
           FROM (transport.bus_routes r
             JOIN transport.bus_stops st ON ((st.stop_code = r.stop_code)))
          GROUP BY r.service_no, r.direction
         HAVING (count(*) FILTER (WHERE st.is_active) > 0)
        ), assessed AS (
         SELECT s.service_no,
            s.direction,
            s.operator,
            s.category,
            first_stop.stop_code AS origin_code,
            first_stop.description AS origin_description,
            last_stop.stop_code AS destination_code,
            last_stop.description AS destination_description,
            (last_route.distance_km - first_route.distance_km) AS known_distance_span_km,
            t.observed_stop_count,
            s.loop_description,
            (t.sequence_gap_free AND ((s.origin_code IS NULL) OR (s.origin_code = first_stop.stop_code)) AND ((s.destination_code IS NULL) OR (s.destination_code = last_stop.stop_code))) AS gap_free
           FROM (((((route_totals t
             JOIN transport.bus_services s ON (((s.service_no = t.service_no) AND (s.direction = t.direction) AND s.is_active)))
             JOIN transport.bus_routes first_route ON (((first_route.service_no = t.service_no) AND (first_route.direction = t.direction) AND (first_route.stop_sequence = t.first_sequence))))
             JOIN transport.bus_stops first_stop ON ((first_stop.stop_code = first_route.stop_code)))
             JOIN transport.bus_routes last_route ON (((last_route.service_no = t.service_no) AND (last_route.direction = t.direction) AND (last_route.stop_sequence = t.last_sequence))))
             JOIN transport.bus_stops last_stop ON ((last_stop.stop_code = last_route.stop_code)))
        )
 SELECT service_no,
    direction,
    operator,
    category,
    origin_code,
    origin_description,
    destination_code,
    destination_description,
        CASE
            WHEN gap_free THEN known_distance_span_km
            ELSE NULL::numeric
        END AS route_length_km,
        CASE
            WHEN gap_free THEN observed_stop_count
            ELSE NULL::bigint
        END AS stop_count,
    loop_description,
        CASE
            WHEN gap_free THEN 'no_detected_gaps'::text
            ELSE 'partial'::text
        END AS route_coverage,
    observed_stop_count,
    known_distance_span_km
   FROM assessed;


--
-- Name: longest_routes(); Type: FUNCTION; Schema: transport; Owner: -
--

CREATE FUNCTION transport.longest_routes() RETURNS SETOF transport.active_route_summaries
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'transport'
    AS $$
    SELECT r.* FROM transport.active_route_summaries AS r
    WHERE r.route_coverage='no_detected_gaps'
    ORDER BY r.route_length_km DESC, r.service_no, r.direction
    LIMIT 10;
$$;


--
-- Name: nearby_stops(double precision, double precision, double precision); Type: FUNCTION; Schema: transport; Owner: -
--

CREATE FUNCTION transport.nearby_stops(p_lat double precision, p_lon double precision, p_radius double precision DEFAULT 500) RETURNS TABLE(stop_code text, description text, road_name text, latitude double precision, longitude double precision, distance_m double precision, services text[])
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'transport'
    AS $$
BEGIN
    IF p_lat IS NULL OR NOT (p_lat BETWEEN -90 AND 90)
       OR p_lon IS NULL OR NOT (p_lon BETWEEN -180 AND 180)
       OR p_radius IS NULL OR NOT (p_radius BETWEEN 1 AND 5000) THEN
        RAISE EXCEPTION 'Coordinates or radius outside the supported range'
            USING ERRCODE = '22023';
    END IF;

    RETURN QUERY
    WITH distances AS (
        SELECT st.stop_code, st.description, st.road_name, st.latitude, st.longitude,
               6371000.0 * 2.0 * asin(sqrt(least(1.0, greatest(0.0,
                   power(sin(radians(st.latitude - p_lat) / 2.0), 2)
                   + cos(radians(p_lat)) * cos(radians(st.latitude))
                     * power(sin(radians(st.longitude - p_lon) / 2.0), 2)
               )))) AS distance_m
        FROM transport.bus_stops AS st
        WHERE st.is_active
    )
    SELECT d.stop_code, d.description, d.road_name, d.latitude, d.longitude,
           d.distance_m,
           (SELECT array_agg(DISTINCT s.service_no ORDER BY s.service_no)
            FROM transport.bus_routes AS r
            JOIN transport.bus_services AS s
              ON s.service_no = r.service_no AND s.direction = r.direction AND s.is_active
            WHERE r.stop_code = d.stop_code) AS services
    FROM distances AS d
    WHERE d.distance_m <= p_radius
    ORDER BY d.distance_m, d.stop_code;
END;
$$;


--
-- Name: FUNCTION nearby_stops(p_lat double precision, p_lon double precision, p_radius double precision); Type: COMMENT; Schema: transport; Owner: -
--

COMMENT ON FUNCTION transport.nearby_stops(p_lat double precision, p_lon double precision, p_radius double precision) IS 'Straight-line haversine distance in metres, not walking distance. NULL services means no imported active route coverage; it does not mean no buses operate.';


--
-- Name: routes_on_road(text); Type: FUNCTION; Schema: transport; Owner: -
--

CREATE FUNCTION transport.routes_on_road(p_name text) RETURNS SETOF transport.active_route_summaries
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'transport'
    AS $$
    SELECT summary.* FROM transport.active_route_summaries AS summary
    WHERE length(btrim(p_name))>0 AND EXISTS (
        SELECT 1 FROM transport.bus_routes AS r
        JOIN transport.bus_stops AS st ON st.stop_code=r.stop_code AND st.is_active
        WHERE r.service_no=summary.service_no AND r.direction=summary.direction
          AND strpos(lower(st.road_name),lower(btrim(p_name)))>0
    )
    ORDER BY summary.service_no, summary.direction;
$$;


